let result = match server.load_audio(cue.clone(), &path, &mut assets) {
    Ok(handle) => match assets.get(&handle) {
        Some(asset) => audio
            .start_voice_at(asset, gains, ticks_to_duration(offset_ticks))
            .map_err(|error| error.to_string()),
        None => Err("decoded audio asset disappeared after loading".to_owned()),
    },
